        KJScene(id: "s209", lap: 2, chapter: 5, face: "npc_friend", ja: "ともだちと やくそく", en: "Making plans with a friend", zh: "和朋友約定", ko: "친구와 약속", lines: [
            .init(me: false, ja: "土曜日、ひまですか。", kana: "どようび、ひまですか。", en: "Are you free on Saturday?", zh: "星期六有空嗎？", ko: "토요일에 한가해요?"),
            .init(me: true, ja: "はい、ひまです。どうしてですか。", kana: "はい、ひまです。どうしてですか。", en: "Yes, I'm free. Why?", zh: "有空，怎麼了？", ko: "네, 한가해요. 왜요?"),
            .init(me: false, ja: "いっしょに 映画を 見ませんか。", kana: "いっしょに えいがを みませんか。", en: "Shall we watch a movie together?", zh: "要不要一起看電影？", ko: "같이 영화 보지 않을래요?"),
            .init(me: true, ja: "いいですね。見ましょう。", kana: "いいですね。みましょう。", en: "Sounds good. Let's watch one.", zh: "好啊，一起看吧。", ko: "좋아요. 봐요."),
            .init(me: false, ja: "何時に 会いましょうか。", kana: "なんじに あいましょうか。", en: "What time shall we meet?", zh: "幾點見面呢？", ko: "몇 시에 만날까요?"),
            .init(me: true, ja: "二時は どうですか。", kana: "にじは どうですか。", en: "How about two o'clock?", zh: "兩點怎麼樣？", ko: "두 시 어때요?"),
            .init(me: false, ja: "いいですよ。どこで 会いますか。", kana: "いいですよ。どこで あいますか。", en: "OK. Where shall we meet?", zh: "好啊，在哪裡見面？", ko: "좋아요. 어디서 만나요?"),
            .init(me: true, ja: "駅の 前で 会いましょう。", kana: "えきの まえで あいましょう。", en: "Let's meet in front of the station.", zh: "在車站前面見吧。", ko: "역 앞에서 만나요."),
            .init(me: false, ja: "じゃあ、土曜日に。", kana: "じゃあ、どようびに。", en: "See you on Saturday, then.", zh: "那就星期六見。", ko: "그럼 토요일에 봐요."),
            .init(me: true, ja: "はい、楽しみに しています。", kana: "はい、たのしみに しています。", en: "Yes, I'm looking forward to it.", zh: "好，我很期待。", ko: "네, 기대하고 있을게요.")]),
        KJScene(id: "s210", lap: 2, chapter: 5, face: "npc_nakamise", ja: "おみやげを かう", en: "Buying souvenirs", zh: "買伴手禮", ko: "기념품 사기", lines: [
            .init(me: false, ja: "いらっしゃい。何を さがして いますか。", kana: "いらっしゃい。なにを さがして いますか。", en: "Welcome. What are you looking for?", zh: "歡迎，在找什麼呢？", ko: "어서 오세요. 뭘 찾아요?"),
            .init(me: true, ja: "家族に おみやげを 買いたいです。", kana: "かぞくに おみやげを かいたいです。", en: "I want to buy souvenirs for my family.", zh: "我想買伴手禮給家人。", ko: "가족에게 기념품을 사고 싶어요."),
            .init(me: false, ja: "この おかしは 人気ですよ。", kana: "この おかしは にんきですよ。", en: "These sweets are popular.", zh: "這個點心很受歡迎喔。", ko: "이 과자가 인기예요."),
            .init(me: true, ja: "いくらですか。", kana: "いくらですか。", en: "How much is it?", zh: "多少錢？", ko: "얼마예요?"),
            .init(me: false, ja: "千二百円です。", kana: "せんにひゃくえんです。", en: "It's 1,200 yen.", zh: "一千兩百日圓。", ko: "1,200엔이에요."),
            .init(me: true, ja: "もう 少し 小さいのは ありますか。", kana: "もう すこし ちいさいのは ありますか。", en: "Do you have a slightly smaller one?", zh: "有小一點的嗎？", ko: "조금 더 작은 거 있어요?"),
            .init(me: false, ja: "はい、こちらは 六百円です。", kana: "はい、こちらは ろっぴゃくえんです。", en: "Yes, this one is 600 yen.", zh: "有，這個六百日圓。", ko: "네, 이건 600엔이에요."),
            .init(me: true, ja: "じゃあ、これを 三つ ください。", kana: "じゃあ、これを みっつ ください。", en: "Then three of these, please.", zh: "那請給我三個。", ko: "그럼 이거 세 개 주세요."),
            .init(me: false, ja: "ありがとう ございます。また どうぞ。", kana: "ありがとう ございます。また どうぞ。", en: "Thank you. Please come again.", zh: "謝謝，歡迎再來。", ko: "감사합니다. 또 오세요."),
            .init(me: true, ja: "ありがとう。さようなら。", kana: "ありがとう。さようなら。", en: "Thanks. Goodbye.", zh: "謝謝，再見。", ko: "고마워요. 안녕히 계세요.")]),
        KJScene(id: "s211", lap: 2, chapter: 6, face: "npc_doctor", ja: "びょういんで", en: "At the doctor's", zh: "在醫院", ko: "병원에서", lines: [
            .init(me: false, ja: "どう しましたか。", kana: "どう しましたか。", en: "What seems to be the problem?", zh: "怎麼了？", ko: "어디가 안 좋으세요?"),
            .init(me: true, ja: "頭が いたいです。", kana: "あたまが いたいです。", en: "I have a headache.", zh: "我頭痛。", ko: "머리가 아파요."),
            .init(me: false, ja: "いつからですか。", kana: "いつからですか。", en: "Since when?", zh: "從什麼時候開始？", ko: "언제부터요?"),
            .init(me: true, ja: "きのうの 夜からです。", kana: "きのうの よるからです。", en: "Since last night.", zh: "從昨天晚上開始。", ko: "어젯밤부터요."),
            .init(me: false, ja: "熱は ありますか。", kana: "ねつは ありますか。", en: "Do you have a fever?", zh: "有發燒嗎？", ko: "열 있어요?"),
            .init(me: true, ja: "はい、少し あります。", kana: "はい、すこし あります。", en: "Yes, a little.", zh: "有，一點點。", ko: "네, 조금 있어요."),
            .init(me: false, ja: "かぜですね。薬を 出します。", kana: "かぜですね。くすりを だします。", en: "It's a cold. I'll give you medicine.", zh: "是感冒，我開藥給你。", ko: "감기네요. 약을 드릴게요."),
            .init(me: true, ja: "薬は いつ 飲みますか。", kana: "くすりは いつ のみますか。", en: "When should I take the medicine?", zh: "藥什麼時候吃？", ko: "약은 언제 먹어요?"),
            .init(me: false, ja: "ご飯の あとに 飲んで ください。", kana: "ごはんの あとに のんで ください。", en: "Take it after meals.", zh: "請飯後吃。", ko: "식사 후에 드세요."),
            .init(me: true, ja: "わかりました。ありがとう ございました。", kana: "わかりました。ありがとう ございました。", en: "I see. Thank you very much.", zh: "我知道了，謝謝。", ko: "알겠어요. 감사합니다.")]),
        KJScene(id: "s212", lap: 2, chapter: 6, face: "npc_nakamise", ja: "しゃしんを とって もらう", en: "Asking someone to take a photo", zh: "請人幫忙拍照", ko: "사진 찍어 달라고 하기", lines: [
            .init(me: true, ja: "すみません、写真を とって くれませんか。", kana: "すみません、しゃしんを とって くれませんか。", en: "Excuse me, could you take a photo for us?", zh: "不好意思，可以幫我們拍照嗎？", ko: "저기요, 사진 좀 찍어 주실래요?"),
            .init(me: false, ja: "いいですよ。どこを おしますか。", kana: "いいですよ。どこを おしますか。", en: "Sure. Where do I press?", zh: "好啊，按哪裡？", ko: "좋아요. 어디를 눌러요?"),
            .init(me: true, ja: "ここを おして ください。", kana: "ここを おして ください。", en: "Please press here.", zh: "請按這裡。", ko: "여기를 눌러 주세요."),
            .init(me: false, ja: "はい、とりますよ。一、二、三！", kana: "はい、とりますよ。いち、に、さん！", en: "OK, here goes. One, two, three!", zh: "要拍了喔，一、二、三！", ko: "자, 찍어요. 하나, 둘, 셋!"),
            .init(me: true, ja: "もう 一枚 おねがいします。", kana: "もう いちまい おねがいします。", en: "One more, please.", zh: "麻煩再一張。", ko: "한 장 더 부탁해요."),
            .init(me: false, ja: "はい、どうぞ。きれいに とれましたよ。", kana: "はい、どうぞ。きれいに とれましたよ。", en: "Here you go. It came out nicely.", zh: "好了，拍得很漂亮喔。", ko: "여기요. 예쁘게 나왔어요."),
            .init(me: true, ja: "ありがとう ございます。", kana: "ありがとう ございます。", en: "Thank you very much.", zh: "謝謝您。", ko: "감사합니다."),
            .init(me: false, ja: "どこから 来ましたか。", kana: "どこから きましたか。", en: "Where are you from?", zh: "你從哪裡來的？", ko: "어디에서 왔어요?"),
            .init(me: true, ja: "台湾から 来ました。", kana: "たいわんから きました。", en: "I'm from Taiwan.", zh: "我從台灣來。", ko: "대만에서 왔어요."),
            .init(me: false, ja: "そうですか。日本を 楽しんで ください。", kana: "そうですか。にほんを たのしんで ください。", en: "I see. Enjoy Japan!", zh: "這樣啊，好好享受日本吧。", ko: "그렇군요. 일본 즐기세요.")]),
        KJScene(id: "s213", lap: 2, chapter: 7, face: "npc_hotel", ja: "でんわで よやく", en: "Booking by phone", zh: "打電話預約", ko: "전화로 예약", lines: [
            .init(me: false, ja: "はい、さくら旅館です。", kana: "はい、さくらりょかんです。", en: "Hello, this is Sakura Inn.", zh: "您好，這裡是櫻花旅館。", ko: "네, 사쿠라 료칸입니다."),
            .init(me: true, ja: "もしもし、予約を したいです。", kana: "もしもし、よやくを したいです。", en: "Hello, I'd like to make a reservation.", zh: "喂，我想預約。", ko: "여보세요, 예약하고 싶어요."),
            .init(me: false, ja: "いつですか。", kana: "いつですか。", en: "For when?", zh: "什麼時候呢？", ko: "언제요?"),
            .init(me: true, ja: "来週の 金曜日です。", kana: "らいしゅうの きんようびです。", en: "Next Friday.", zh: "下週五。", ko: "다음 주 금요일이요."),
            .init(me: false, ja: "何名さまですか。", kana: "なんめいさまですか。", en: "For how many people?", zh: "幾位呢？", ko: "몇 분이세요?"),
            .init(me: true, ja: "三人です。", kana: "さんにんです。", en: "Three people.", zh: "三位。", ko: "세 명이요."),
            .init(me: false, ja: "一泊 一人 八千円です。", kana: "いっぱく ひとり はっせんえんです。", en: "It's 8,000 yen per person per night.", zh: "一晚一人八千日圓。", ko: "1박에 한 명 8,000엔이에요."),
            .init(me: true, ja: "はい、それで おねがいします。", kana: "はい、それで おねがいします。", en: "OK, please book that.", zh: "好，就這樣麻煩了。", ko: "네, 그걸로 부탁해요."),
            .init(me: false, ja: "お電話番号を おねがいします。", kana: "おでんわばんごうを おねがいします。", en: "Your phone number, please.", zh: "請告訴我電話號碼。", ko: "전화번호를 부탁드려요."),
            .init(me: true, ja: "〇九〇の 一二三四の 五六七八です。", kana: "ゼロきゅうゼロの いちにさんよんの ごろくななはちです。", en: "It's 090-1234-5678.", zh: "是090-1234-5678。", ko: "090-1234-5678이에요.")]),
        KJScene(id: "s214", lap: 2, chapter: 7, face: "npc_grandma", ja: "おれいと おわかれ", en: "Thanks and goodbye", zh: "道謝與道別", ko: "인사와 작별", lines: [
            .init(me: false, ja: "もう 帰りますか。さびしいですね。", kana: "もう かえりますか。さびしいですね。", en: "Leaving already? I'll miss you.", zh: "要回去了嗎？好捨不得。", ko: "벌써 가요? 섭섭하네요."),
            .init(me: true, ja: "はい。本当に おせわに なりました。", kana: "はい。ほんとうに おせわに なりました。", en: "Yes. Thank you so much for everything.", zh: "是的，真的受您照顧了。", ko: "네. 정말 신세 많이 졌어요."),
            .init(me: false, ja: "また 沖縄に 来て くださいね。", kana: "また おきなわに きて くださいね。", en: "Please come to Okinawa again.", zh: "要再來沖繩喔。", ko: "또 오키나와에 오세요."),
            .init(me: true, ja: "はい、ぜったい また 来ます。", kana: "はい、ぜったい また きます。", en: "Yes, I'll definitely come back.", zh: "好，一定會再來。", ko: "네, 꼭 또 올게요."),
            .init(me: false, ja: "これ、おみやげです。どうぞ。", kana: "これ、おみやげです。どうぞ。", en: "This is a souvenir for you.", zh: "這是伴手禮，請收下。", ko: "이거 선물이에요. 받으세요."),
            .init(me: true, ja: "わあ、ありがとう ございます。", kana: "わあ、ありがとう ございます。", en: "Wow, thank you very much.", zh: "哇，謝謝您。", ko: "와, 감사합니다."),
            .init(me: false, ja: "手紙を 書いて くださいね。", kana: "てがみを かいて くださいね。", en: "Please write me a letter.", zh: "要寫信給我喔。", ko: "편지 써 주세요."),
            .init(me: true, ja: "はい、日本語で 書きます。", kana: "はい、にほんごで かきます。", en: "Yes, I'll write in Japanese.", zh: "好，我會用日語寫。", ko: "네, 일본어로 쓸게요."),
            .init(me: false, ja: "元気で ね。", kana: "げんきで ね。", en: "Take care of yourself.", zh: "保重喔。", ko: "잘 지내요."),
            .init(me: true, ja: "お元気で。さようなら。", kana: "おげんきで。さようなら。", en: "You too. Goodbye.", zh: "您也保重，再見。", ko: "건강하세요. 안녕히 계세요.")]),
        KJScene(id: "s301", lap: 3, chapter: 1, face: "npc_boss", ja: "アルバイトの めんせつ", en: "A part-time job interview", zh: "打工面試", ko: "아르바이트 면접", lines: [
            .init(me: false, ja: "どうして この 店で 働きたいんですか。", kana: "どうして この みせで はたらきたいんですか。", en: "Why do you want to work at this shop?", zh: "為什麼想在這家店工作？", ko: "왜 이 가게에서 일하고 싶어요?"),
            .init(me: true, ja: "日本語を 使う 仕事が したいからです。", kana: "にほんごを つかう しごとが したいからです。", en: "Because I want a job where I use Japanese.", zh: "因為我想做用日語的工作。", ko: "일본어를 쓰는 일을 하고 싶어서요."),
            .init(me: false, ja: "前に アルバイトを した ことが ありますか。", kana: "まえに アルバイトを した ことが ありますか。", en: "Have you done part-time work before?", zh: "以前打過工嗎？", ko: "전에 아르바이트를 해 본 적 있어요?"),
            .init(me: true, ja: "はい、国で 喫茶店で 働いた ことが あります。", kana: "はい、くにで きっさてんで はたらいた ことが あります。", en: "Yes, I worked at a café in my country.", zh: "有，在我國家的咖啡廳工作過。", ko: "네, 고향에서 카페에서 일한 적이 있어요."),
            .init(me: false, ja: "週に 何日 来られますか。", kana: "しゅうに なんにち こられますか。", en: "How many days a week can you come?", zh: "一週可以來幾天？", ko: "일주일에 며칠 올 수 있어요?"),
            .init(me: true, ja: "三日ぐらい 来られると 思います。", kana: "みっかぐらい こられると おもいます。", en: "I think I can come about three days.", zh: "我想大概可以來三天。", ko: "사흘 정도 올 수 있을 것 같아요."),
            .init(me: false, ja: "朝 早くても 大丈夫ですか。", kana: "あさ はやくても だいじょうぶですか。", en: "Is it OK even early in the morning?", zh: "早上很早也沒問題嗎？", ko: "아침 일찍이라도 괜찮아요?"),
            .init(me: true, ja: "はい、早く 起きるのは 得意です。", kana: "はい、はやく おきるのは とくいです。", en: "Yes, I'm good at getting up early.", zh: "沒問題，我很會早起。", ko: "네, 일찍 일어나는 건 자신 있어요."),
            .init(me: false, ja: "じゃあ、来週から 来て ください。", kana: "じゃあ、らいしゅうから きて ください。", en: "Then please start next week.", zh: "那請從下週開始來。", ko: "그럼 다음 주부터 와 주세요."),
            .init(me: true, ja: "ありがとう ございます。がんばります。", kana: "ありがとう ございます。がんばります。", en: "Thank you very much. I'll do my best.", zh: "謝謝您，我會加油的。", ko: "감사합니다. 열심히 할게요.")]),
        KJScene(id: "s302", lap: 3, chapter: 2, face: "npc_police", ja: "おとしものを さがす", en: "Looking for something you lost", zh: "找遺失物", ko: "분실물 찾기", lines: [
            .init(me: true, ja: "すみません、財布を なくして しまいました。", kana: "すみません、さいふを なくして しまいました。", en: "Excuse me, I've lost my wallet.", zh: "不好意思，我把錢包弄丟了。", ko: "저기요, 지갑을 잃어버렸어요."),
            .init(me: false, ja: "どこで なくしたか わかりますか。", kana: "どこで なくしたか わかりますか。", en: "Do you know where you lost it?", zh: "知道在哪裡弄丟的嗎？", ko: "어디서 잃어버렸는지 알아요?"),
            .init(me: true, ja: "たぶん 駅の 近くだと 思います。", kana: "たぶん えきの ちかくだと おもいます。", en: "I think it was probably near the station.", zh: "我想大概是在車站附近。", ko: "아마 역 근처인 것 같아요."),
            .init(me: false, ja: "どんな 財布ですか。", kana: "どんな さいふですか。", en: "What kind of wallet is it?", zh: "是什麼樣的錢包？", ko: "어떤 지갑이에요?"),
            .init(me: true, ja: "黒くて 小さい 財布です。", kana: "くろくて ちいさい さいふです。", en: "A small black wallet.", zh: "黑色的小錢包。", ko: "검고 작은 지갑이에요."),
            .init(me: false, ja: "中に 何が 入って いましたか。", kana: "なかに なにが はいって いましたか。", en: "What was inside?", zh: "裡面有什麼？", ko: "안에 뭐가 들어 있었어요?"),
            .init(me: true, ja: "お金と カードが 入って いました。", kana: "おかねと カードが はいって いました。", en: "Money and cards.", zh: "有錢和卡片。", ko: "돈이랑 카드가 들어 있었어요."),
            .init(me: false, ja: "この 紙に 住所と 名前を 書いて ください。", kana: "この かみに じゅうしょと なまえを かいて ください。", en: "Please write your address and name on this paper.", zh: "請在這張紙上寫地址和名字。", ko: "이 종이에 주소와 이름을 써 주세요."),
            .init(me: true, ja: "見つかったら、電話して もらえますか。", kana: "みつかったら、でんわして もらえますか。", en: "Could you call me if it's found?", zh: "如果找到了，可以打電話給我嗎？", ko: "찾으면 전화해 주실 수 있어요?"),
            .init(me: false, ja: "はい、すぐに 連絡します。", kana: "はい、すぐに れんらくします。", en: "Yes, we'll contact you right away.", zh: "好的，會馬上聯絡你。", ko: "네, 바로 연락할게요.")]),
        KJScene(id: "s303", lap: 3, chapter: 3, face: "npc_nakamise", ja: "みちに まよった", en: "Lost your way", zh: "迷路了", ko: "길을 잃었어요", lines: [
            .init(me: true, ja: "すみません、道に まよって しまったんですが…。", kana: "すみません、みちに まよって しまったんですが…。", en: "Excuse me, I seem to have got lost...", zh: "不好意思，我好像迷路了……", ko: "저기요, 길을 잃어버렸는데요..."),
            .init(me: false, ja: "どこへ 行きたいんですか。", kana: "どこへ いきたいんですか。", en: "Where do you want to go?", zh: "你想去哪裡？", ko: "어디에 가고 싶어요?"),
            .init(me: true, ja: "運河の 近くの 美術館へ 行きたいです。", kana: "うんがの ちかくの びじゅつかんへ いきたいです。", en: "I want to go to the museum near the canal.", zh: "我想去運河附近的美術館。", ko: "운하 근처 미술관에 가고 싶어요."),
            .init(me: false, ja: "それなら、二つ目の 角を 左に 曲がって ください。", kana: "それなら、ふたつめの かどを ひだりに まがって ください。", en: "Then turn left at the second corner.", zh: "那請在第二個轉角左轉。", ko: "그럼 두 번째 모퉁이에서 왼쪽으로 도세요."),
            .init(me: true, ja: "歩いて 行けますか。", kana: "あるいて いけますか。", en: "Can I walk there?", zh: "走得到嗎？", ko: "걸어서 갈 수 있어요?"),
            .init(me: false, ja: "はい、十分ぐらいで 着くと 思いますよ。", kana: "はい、じゅっぷんぐらいで つくと おもいますよ。", en: "Yes, I think you'll get there in about ten minutes.", zh: "可以，我想十分鐘左右就到了。", ko: "네, 10분쯤이면 도착할 거예요."),
            .init(me: true, ja: "地図を 書いて いただけませんか。", kana: "ちずを かいて いただけませんか。", en: "Could you draw me a map?", zh: "可以幫我畫張地圖嗎？", ko: "지도를 그려 주실 수 있어요?"),
            .init(me: false, ja: "いいですよ。ここが 今 いる 所です。", kana: "いいですよ。ここが いま いる ところです。", en: "Sure. This is where we are now.", zh: "好啊，這裡是現在的位置。", ko: "좋아요. 여기가 지금 있는 곳이에요."),
            .init(me: true, ja: "本当に 助かりました。", kana: "ほんとうに たすかりました。", en: "You've really helped me.", zh: "真的幫了大忙。", ko: "정말 도움이 됐어요."),
            .init(me: false, ja: "気を つけて 行って くださいね。", kana: "きを つけて いって くださいね。", en: "Take care on your way.", zh: "路上小心喔。", ko: "조심히 가세요.")]),
        KJScene(id: "s304", lap: 3, chapter: 4, face: "npc_hotel", ja: "よやくを かえる", en: "Changing a reservation", zh: "更改預約", ko: "예약 변경", lines: [
            .init(me: true, ja: "予約を 変更したいんですが。", kana: "よやくを へんこうしたいんですが。", en: "I'd like to change my reservation.", zh: "我想更改預約。", ko: "예약을 변경하고 싶은데요."),
            .init(me: false, ja: "はい、お名前を うかがっても よろしいですか。", kana: "はい、おなまえを うかがっても よろしいですか。", en: "Certainly. May I have your name?", zh: "好的，可以請教您的大名嗎？", ko: "네, 성함을 여쭤봐도 될까요?"),
            .init(me: true, ja: "ユイです。十日から 二泊です。", kana: "ユイです。とおかから にはくです。", en: "I'm Yui. Two nights from the tenth.", zh: "我是結衣，十號開始住兩晚。", ko: "유이예요. 10일부터 2박이에요."),
            .init(me: false, ja: "どのように 変更なさいますか。", kana: "どのように へんこうなさいますか。", en: "How would you like to change it?", zh: "請問要怎麼更改呢？", ko: "어떻게 변경하시겠어요?"),
            .init(me: true, ja: "一日 おそくして もらえますか。", kana: "いちにち おそくして もらえますか。", en: "Could you make it one day later?", zh: "可以延後一天嗎？", ko: "하루 늦춰 주실 수 있어요?"),
            .init(me: false, ja: "十一日からですね。少々 お待ちください。", kana: "じゅういちにちからですね。しょうしょう おまちください。", en: "From the eleventh. One moment, please.", zh: "從十一號開始對吧。請稍等。", ko: "11일부터요. 잠시만 기다려 주세요."),
            .init(me: false, ja: "申し訳ありませんが、和室しか ありません。", kana: "もうしわけ ありませんが、わしつしか ありません。", en: "I'm sorry, but only Japanese-style rooms are left.", zh: "很抱歉，只剩下和室了。", ko: "죄송하지만 다다미방밖에 없어요."),
            .init(me: true, ja: "和室でも かまいません。", kana: "わしつでも かまいません。", en: "A Japanese-style room is fine.", zh: "和室也沒關係。", ko: "다다미방이라도 괜찮아요."),
            .init(me: false, ja: "かしこまりました。変更して おきます。", kana: "かしこまりました。へんこうして おきます。", en: "Certainly. I'll change it for you.", zh: "好的，我幫您更改。", ko: "알겠습니다. 변경해 두겠습니다."),
            .init(me: true, ja: "よろしく お願いします。", kana: "よろしく おねがいします。", en: "Thank you, I appreciate it.", zh: "麻煩您了。", ko: "잘 부탁드려요.")]),
        KJScene(id: "s305", lap: 3, chapter: 5, face: "npc_friend", ja: "さそう・ことわる", en: "Inviting and saying no", zh: "邀約與婉拒", ko: "권하기・거절하기", lines: [
            .init(me: false, ja: "今晩、たこやきパーティーを するんだけど、来ない？", kana: "こんばん、たこやきパーティーを するんだけど、こない？", en: "We're having a takoyaki party tonight. Want to come?", zh: "今晚要辦章魚燒派對，要來嗎？", ko: "오늘 밤 다코야키 파티 하는데 안 올래?"),
            .init(me: true, ja: "行きたいけど、今日は ちょっと…。", kana: "いきたいけど、きょうは ちょっと…。", en: "I'd like to, but today's a bit...", zh: "我想去，可是今天有點……", ko: "가고 싶은데 오늘은 좀..."),
            .init(me: false, ja: "何か 用事が あるの？", kana: "なにか ようじが あるの？", en: "Do you have something on?", zh: "有什麼事嗎？", ko: "무슨 볼일 있어?"),
            .init(me: true, ja: "あした 試験が あるから、勉強しなければ ならないんだ。", kana: "あした しけんが あるから、べんきょうしなければ ならないんだ。", en: "I have an exam tomorrow, so I have to study.", zh: "明天有考試，所以得念書。", ko: "내일 시험이 있어서 공부해야 해."),
            .init(me: false, ja: "そうか。がんばってね。", kana: "そうか。がんばってね。", en: "I see. Good luck!", zh: "這樣啊，加油喔。", ko: "그렇구나. 힘내."),
            .init(me: true, ja: "ありがとう。また さそって ね。", kana: "ありがとう。また さそって ね。", en: "Thanks. Invite me again.", zh: "謝謝，下次再約我喔。", ko: "고마워. 또 불러 줘."),
            .init(me: false, ja: "じゃあ、来週の 日曜日は どう？", kana: "じゃあ、らいしゅうの にちようびは どう？", en: "Then how about next Sunday?", zh: "那下週日怎麼樣？", ko: "그럼 다음 주 일요일은 어때?"),
            .init(me: true, ja: "日曜日なら 大丈夫だよ。", kana: "にちようびなら だいじょうぶだよ。", en: "Sunday is fine.", zh: "星期天的話沒問題。", ko: "일요일이면 괜찮아."),
            .init(me: false, ja: "よかった！ 何か 持って きて くれる？", kana: "よかった！ なにか もって きて くれる？", en: "Great! Can you bring something?", zh: "太好了！可以帶點東西來嗎？", ko: "잘됐다! 뭐 좀 가져와 줄래?"),
            .init(me: true, ja: "うん、飲み物を 持って いくよ。", kana: "うん、のみものを もって いくよ。", en: "Sure, I'll bring drinks.", zh: "好，我帶飲料去。", ko: "응, 음료수 가져갈게.")]),
        KJScene(id: "s306", lap: 3, chapter: 6, face: "npc_doctor", ja: "しょうじょうを せつめいする", en: "Explaining your symptoms", zh: "說明症狀", ko: "증상 설명하기", lines: [
            .init(me: false, ja: "今日は どう されましたか。", kana: "きょうは どう されましたか。", en: "What brings you here today?", zh: "今天怎麼了？", ko: "오늘은 어디가 불편하세요?"),
            .init(me: true, ja: "三日前から のどが 痛くて、せきが 出ます。", kana: "みっかまえから のどが いたくて、せきが でます。", en: "My throat has hurt for three days and I'm coughing.", zh: "三天前開始喉嚨痛，還會咳嗽。", ko: "사흘 전부터 목이 아프고 기침이 나요."),
            .init(me: false, ja: "熱は 何度 ありましたか。", kana: "ねつは なんど ありましたか。", en: "How high was your fever?", zh: "發燒幾度？", ko: "열은 몇 도였어요?"),
            .init(me: true, ja: "ゆうべは 三十八度でした。", kana: "ゆうべは さんじゅうはちどでした。", en: "Last night it was 38 degrees.", zh: "昨晚是三十八度。", ko: "어젯밤에는 38도였어요."),
            .init(me: false, ja: "薬は 何か 飲みましたか。", kana: "くすりは なにか のみましたか。", en: "Have you taken any medicine?", zh: "有吃什麼藥嗎？", ko: "약은 뭐 드셨어요?"),
            .init(me: true, ja: "いいえ、何も 飲んで いません。", kana: "いいえ、なにも のんで いません。", en: "No, I haven't taken anything.", zh: "沒有，什麼都沒吃。", ko: "아니요, 아무것도 안 먹었어요."),
            .init(me: false, ja: "かぜだと 思います。三日分の 薬を 出しますね。", kana: "かぜだと おもいます。みっかぶんの くすりを だしますね。", en: "I think it's a cold. I'll give you three days of medicine.", zh: "我想是感冒，開三天份的藥。", ko: "감기 같아요. 사흘 치 약을 드릴게요."),
            .init(me: true, ja: "お風呂に 入っても いいですか。", kana: "おふろに はいっても いいですか。", en: "Is it OK to take a bath?", zh: "可以泡澡嗎？", ko: "목욕해도 돼요?"),
            .init(me: false, ja: "熱が あるうちは 入らない ほうが いいですよ。", kana: "ねつが あるうちは はいらない ほうが いいですよ。", en: "Better not while you have a fever.", zh: "發燒的時候最好不要泡。", ko: "열이 있는 동안은 안 하는 게 좋아요."),
            .init(me: true, ja: "わかりました。ありがとう ございました。", kana: "わかりました。ありがとう ございました。", en: "I understand. Thank you very much.", zh: "我知道了，謝謝。", ko: "알겠어요. 감사합니다.")]),
        KJScene(id: "s307", lap: 3, chapter: 7, face: "npc_teacher", ja: "せんせいに おねがい", en: "Asking your teacher a favor", zh: "拜託老師", ko: "선생님께 부탁", lines: [
            .init(me: true, ja: "先生、少し お時間 よろしいですか。", kana: "せんせい、すこし おじかん よろしいですか。", en: "Teacher, do you have a moment?", zh: "老師，可以耽誤您一點時間嗎？", ko: "선생님, 잠깐 시간 괜찮으세요?"),
