            .init(me: true, ja: "十二月です。作文を 見て いただけませんか。", kana: "じゅうにがつです。さくぶんを みて いただけませんか。", en: "In December. Could you look at my essay?", zh: "十二月。可以幫我看作文嗎？", ko: "12월이에요. 작문을 봐 주실 수 있으세요?"),
            .init(me: false, ja: "いいですよ。あした 持って きて ください。", kana: "いいですよ。あした もって きて ください。", en: "Sure. Please bring it tomorrow.", zh: "好啊，明天帶來吧。", ko: "좋아요. 내일 가져오세요."),
            .init(me: true, ja: "ありがとう ございます。それから、おすすめの 本は ありますか。", kana: "ありがとう ございます。それから、おすすめの ほんは ありますか。", en: "Thank you. Also, is there a book you'd recommend?", zh: "謝謝。還有，有推薦的書嗎？", ko: "감사합니다. 그리고 추천하는 책 있으세요?"),
            .init(me: false, ja: "この 本を 毎日 少しずつ 読むと いいですよ。", kana: "この ほんを まいにち すこしずつ よむと いいですよ。", en: "Reading this book a little every day is good.", zh: "每天讀一點這本書就好。", ko: "이 책을 매일 조금씩 읽으면 좋아요."),
            .init(me: true, ja: "さっそく 読んで みます。", kana: "さっそく よんで みます。", en: "I'll start reading it right away.", zh: "我馬上來讀讀看。", ko: "바로 읽어 볼게요."),
            .init(me: false, ja: "がんばって ください。きっと 合格できますよ。", kana: "がんばって ください。きっと ごうかくできますよ。", en: "Do your best. I'm sure you'll pass.", zh: "加油，一定會考上的。", ko: "힘내세요. 꼭 합격할 거예요.")]),
        KJScene(id: "s308", lap: 3, chapter: 1, face: "npc_friend", ja: "ともだちの いえで", en: "At a friend's house", zh: "在朋友家", ko: "친구 집에서", lines: [
            .init(me: false, ja: "いらっしゃい。どうぞ 上がって。", kana: "いらっしゃい。どうぞ あがって。", en: "Welcome. Come on in.", zh: "歡迎，請進。", ko: "어서 와. 들어와."),
