            .init(me: true, ja: "じゃあ、お茶を いただきます。", kana: "じゃあ、おちゃを いただきます。", en: "Then I'll have some tea, thank you.", zh: "那我喝茶，謝謝。", ko: "그럼 차를 마실게요."),
            .init(me: false, ja: "写真を 見せて あげるね。", kana: "しゃしんを みせて あげるね。", en: "I'll show you some photos.", zh: "我給你看照片喔。", ko: "사진 보여 줄게."),
            .init(me: true, ja: "わあ、これは どこで とったんですか。", kana: "わあ、これは どこで とったんですか。", en: "Wow, where did you take this?", zh: "哇，這是在哪裡拍的？", ko: "와, 이건 어디서 찍었어요?"),
            .init(me: false, ja: "去年 北海道へ 行った ときの 写真だよ。", kana: "きょねん ほっかいどうへ いった ときの しゃしんだよ。", en: "It's from when I went to Hokkaido last year.", zh: "是去年去北海道時拍的。", ko: "작년에 홋카이도 갔을 때 사진이야."),
